-- 월드미션타임즈: 첫 기사 10건 (승인대기) — 해외 선교 언론 보도 8건 + 편집국 해설 2건
-- Supabase SQL 에디터에서 실행 (seed-worldmissiontimes.sql 다음). 여러 번 실행해도 된다 (같은 제목 기사는 건너뛴다)
--   · 해외: 국제기독연대(ICC)·크리스채너티투데이(CT)·IMB(미국 남침례교 국제선교이사회) 공개 기사에서 사실만 골라 새로 썼고,
--           본문에 출처 매체를 밝혔다. 원문 사진은 저작권 때문에 쓰지 않았다
--   · 선교지 보안: 박해·제한 지역의 선교사·현지 신자 이름과 구체적 위치는 쓰지 않았다
--   · 사진: 위키미디어 공용·플리커의 공개 라이선스 사진(CC0·CC BY·CC BY-SA)을 찾아 넣고 사진 설명에 작가·출처·라이선스를 밝혔다
--   · 편집국 해설: '왜 치앙마이에서 시작하는가', '숫자로 본 한국선교 2024'
--   · 기사마다 '확인할 점'과 원문 주소를 AI 메모(편집 메모)에 남겼다
--   · 상태 '승인대기': 편집국 → 기사목록에서 읽어 보고 승인(일괄 승인 가능)하면 홈페이지에 나간다
--   · 작성: 월드미션타임즈 관리자 계정(없으면 편집장 → 총관리자), 기자명 '관리자', 기자 이메일 없음
--   · 섹션: asia-northeast 1, asia-south 1, asia-southeast 2, ch-mobilization 1, cm-field 1, trends 1, trends-data 1, up-bible 1, world-americas 1

with ctx as (
  select o.id as outlet_id, o.name as outlet_name,
         coalesce(
           (select p.id from profiles p where p.outlet_id = o.id and p.role = 'admin' order by p.created_at limit 1),
           (select p.id from profiles p where p.outlet_id = o.id and p.role = 'editor' order by p.created_at limit 1),
           (select p.id from profiles p where (to_jsonb(p) ->> 'is_super') = 'true' order by p.created_at limit 1),
           (select p.id from profiles p where p.role = 'admin' order by p.created_at limit 1)
         ) as author_id
  from outlets o
  where o.name = '월드미션타임즈'
)
insert into articles (outlet_id, category_id, author_id, title, body, excerpt, thumbnail_url, status, published_at, tags, press_release_id)
select ctx.outlet_id, c.id, ctx.author_id, v.title,
       replace(v.body, '@@BYLINE@@', '[' || ctx.outlet_name || '=관리자 기자]'),
       v.excerpt, v.thumb, 'in_review', v.published_at, v.tags,
       null
from ctx
cross join (values
  ('asia-south', '네팔 경찰, 신학교 모임 참석한 한국인 기독교인 24명 체포', '<p>@@BYLINE@@&nbsp;네팔 경찰이 한국인 기독교인 24명을 체포했다고 기독교 박해감시단체 국제기독연대(ICC)가 13일(현지시간) 보도했다. ICC에 따르면 이들은 ''불법적인 종교 교육과 훈련, 전파'' 혐의로 고발이 접수된 뒤 체포됐다.</p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Corn_field_Koshi_Province_Morang_district_Nepal_East.jpg/1280px-Corn_field_Koshi_Province_Morang_district_Nepal_East.jpg" alt="네팔 동부 코시주 모랑 지역의 들녘. 자료 사진 (사진=Khadkag45, 위키미디어 공용, CC BY-SA 4.0)"><p><em>▲ 네팔 동부 코시주 모랑 지역의 들녘. 자료 사진 (사진=Khadkag45, 위키미디어 공용, CC BY-SA 4.0)</em></p><p>ICC는 네팔과 한국의 소식통을 인용해 이들이 지난 9일 네팔 모랑(Morang) 지역의 한 신학교에서 열린 모임에 참석했다가 체포됐다고 전했다. 이 신학교는 2013년부터 네팔 기독교인을 대상으로 신학 과정을 운영해 왔다. 체포된 이들의 신원이나 이후 처리 상황은 보도에 나오지 않았다.</p><p>학교 측은 공개적인 전도 활동이 아니었다고 반박했다. 이 신학교 교장은 UCA뉴스에 "방문자들은 현지 신학교 안에서 신자들과 교류했을 뿐, 개종을 목적으로 공개적으로 설교하거나 복음을 전한 것이 아니었다"고 말했다. ICC는 이번 체포로 국가가 기독교인을 겨냥해 적대하고 있다는 우려가 커지고 있다고 전했다.</p><p>ICC는 이번 사건을 네팔에서 커지고 있는 기독교 활동에 대한 적대의 또 다른 사례로 규정했다. ICC에 따르면 네팔은 인구의 80% 이상이 힌두교인이며, 기독교인은 약 150만 명으로 전체 인구의 5% 수준이지만 빠르게 늘고 있다. ICC는 네팔 신자들이 최근까지는 이웃 인도의 기독교인들보다 국가 차원의 차별과 폭력에서 비교적 보호받아 왔지만 상황이 바뀌고 있다고 주장했다.</p><p>ICC는 또 여러 보고를 근거로 인도의 친힌두 민족주의 세력에서 네팔로 자금이 흘러들어 종교적 소수자에 대한 폭력이 늘었다는 정황이 있다고 주장했다. ICC는 기독교인뿐 아니라 무슬림과 불교인의 종교 시설과 의식, 개인도 공격 대상이 되고 있다고 덧붙였다. 이 같은 주장에 대한 네팔이나 인도 당국의 입장은 보도에 포함되지 않았다.</p><p>ICC는 네팔과 러시아 등에서 한국인 기독교인과 선교사가 체포·구금되거나 차별을 받는 사례가 늘고 있다는 보고도 이어지고 있다고 전했다. 이번 체포와 관련한 한국 정부나 관련 단체의 공식 발표는 보도에 포함되지 않았다.</p><p>네팔에서 사역하거나 방문·단기선교를 계획하는 한국 교회와 선교단체는 현지 법규와 상황을 더욱 면밀히 살필 필요가 있다. 체포된 이들의 안전과 조속한 문제 해결을 위한 관심이 요구된다.</p>', '네팔 경찰이 ''불법 종교 교육·훈련·전파'' 혐의 고발을 근거로 현지 신학교 모임에 참석한 한국인 기독교인 24명을 체포했다고 국제기독연대(ICC)가 전했다. 학교 측은 공개 전도 활동이 아니었다고 반박했다.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Corn_field_Koshi_Province_Morang_district_Nepal_East.jpg/1280px-Corn_field_Koshi_Province_Morang_district_Nepal_East.jpg', '2026-10-14T09:00:00+09:00'::timestamptz, array['네팔','한국인 체포','종교자유','박해','남아시아']::text[], 'wmt-src-00'),
  ('up-bible', '"5억 명 넘는 기독교인, 성경 접근 제한된 나라에 산다"', '<p>@@BYLINE@@&nbsp;전 세계 5억 명이 넘는 기독교인이 성경 접근이 제한된 나라에 살고 있다는 조사 결과가 나왔다. 국제기독연대(ICC)는 여러 사역 단체가 함께 참여한 ''성경 접근 이니셔티브(Bible Access Initiative)''의 연구 결과를 13일(현지시간) 소개했다.</p><img src="https://live.staticflickr.com/5077/5811115037_d41365b3c0_b.jpg" alt="펼쳐 놓은 성경. 자료 사진 (사진=Ryk Neethling, 플리커, CC BY 2.0)"><p><em>▲ 펼쳐 놓은 성경. 자료 사진 (사진=Ryk Neethling, 플리커, CC BY 2.0)</em></p><p>ICC에 따르면 연구팀은 1억 2,500만 명이 넘는 신자가 어떤 형태로도 성경을 접할 수 없는 곳에 살고 있다는 사실도 확인했다. 연구팀은 박해와 빈곤, 문맹, 정치적 규제, 인터넷 접근 부족을 성경 접근을 가로막는 주요 장벽으로 꼽았다.</p><p>연구팀은 조사 결과를 바탕으로 두 가지 목록을 만들었다. 하나는 성경 접근이 가장 심하게 제한된 나라를 정리한 ''성경 제한 목록(Bible Restrictions List)''이고, 다른 하나는 성경 부족이 가장 심각한 나라를 모은 ''성경 부족 목록(Bible Shortages List)''이다.</p><p>성경 제한 목록 상위 10개국은 아프가니스탄, 예멘, 소말리아, 북한, 에리트레아, 모리타니, 투르크메니스탄, 리비아, 수단, 이란이다. 중동과 아프리카, 중앙아시아 국가들과 함께 북한이 이름을 올렸다.</p><p>성경 부족 목록에는 콩고민주공화국(DRC), 에티오피아, 나이지리아, 인도, 우간다, 탄자니아, 중국, 인도네시아, 앙골라, 모잠비크 등 10개국이 올랐다. 이 가운데 7개국은 아프리카, 3개국은 아시아 국가다.</p><p>이번 조사는 성경 접근 문제가 법적 규제만이 아니라 빈곤과 문맹, 인터넷 환경 같은 조건과도 맞물려 있음을 보여준다. 성경번역과 성경 보급에 힘써 온 한국 교회와 선교단체에도 제한 지역과 부족 지역을 구분해 접근해야 한다는 과제를 던진다. 특히 북한이 제한 목록 상위 10개국에 포함됐다는 점은 한국 교회가 계속 주목해야 할 대목이다.</p>', '여러 사역 단체가 참여한 ''성경 접근 이니셔티브(Bible Access Initiative)'' 조사에서 5억 명이 넘는 기독교인이 성경 접근이 제한된 나라에 살고, 1억 2,500만 명 이상은 어떤 형태로도 성경을 구할 수 없는 것으로 나타났다.', 'https://live.staticflickr.com/5077/5811115037_d41365b3c0_b.jpg', '2026-10-14T08:00:00+09:00'::timestamptz, array['성경 접근','성경 보급','박해','북한']::text[], 'wmt-src-01'),
  ('asia-southeast', '미얀마 카친주서 군부 연계 민병대가 교회 두 곳 점거', '<p>@@BYLINE@@&nbsp;미얀마 카친주에서 군사정권과 연계된 민병대가 교회 두 곳을 군사 목적으로 사용하고 있다고 국제기독연대(ICC)가 13일(현지시간) 보도했다. ICC에 따르면 미국에 본부를 둔 버마연구소(BRI)는 모닌(Mohnyin) 타운십의 난문침례교회(Nant Mun Baptist Church)에서 민병대 수료식이 열렸다는 보고를 확인했다.</p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Myitkyina%2C_Myanmar_%28Burma%29_-_panoramio_%281%29.jpg/1280px-Myitkyina%2C_Myanmar_%28Burma%29_-_panoramio_%281%29.jpg" alt="미얀마 카친주의 주도 미치나 시내. 자료 사진 (사진=mohigan, 위키미디어 공용, CC BY-SA 3.0)"><p><em>▲ 미얀마 카친주의 주도 미치나 시내. 자료 사진 (사진=mohigan, 위키미디어 공용, CC BY-SA 3.0)</em></p><p>수료식을 연 곳은 군정과 손잡은 샨니민족군(SNA)으로, 행사는 9월에 열렸다. BRI에 정보를 준 소식통들은 행사 도중 민병대원들이 예배당 안에서 춤을 추고 술을 마셨다고 전했다. 성요셉가톨릭교회의 한 건물은 민병대 본부로 쓰이고 있으며, 같은 단지 안의 다른 건물은 민병대에 의해 약탈당했다.</p><p>UCA뉴스에 따르면 SNA와 미얀마군의 합동 병력이 두 교회를 모두 점거하고 있다. SNA는 침례교회를 군사 훈련장으로도 사용해 왔으며, 소식통들은 지금까지 신병 여섯 기수가 이곳에서 훈련을 받았다고 전했다.</p><p>주로 불교도인 샨니족을 대표하는 SNA는 군정 편에 서서 카친독립군(KIA) 등 다른 소수민족 무장단체와 싸워 왔다. 2024년 말 군정·SNA 합동 병력이 난문 지역으로 진격하면서 수백 가구의 기독교인 가정이 피란했다. 주민들에 따르면 현재 남아 있는 카친 기독교인 가정은 약 80가구로, 상당수는 경제적 어려움과 이동 제한 때문에 떠나지 못하고 있다.</p><p>카친족은 대부분 기독교인으로, 카친주는 미얀마 안에서도 기독교 인구 비중이 유난히 높은 지역이다. ICC는 이번 일이 주민 다수가 피란한 카친주에서 군이 기독교 종교 시설을 점거하고 훼손해 온 광범위한 흐름의 일부라고 지적했다. 지난 6월 9일에는 군정이 장악한 미얀마 대법원이 침례교 목회자 3명의 기독교 혼례 주례 자격을 박탈하는 명령을 내리기도 했다.</p><p>미국 내 카친 교계 지도자들은 교회 점거를 규탄하며 트럼프 행정부의 대응을 촉구했다. BRI의 조 툼 흐뭉(Zo Tum Hmung) 대표는 "버마 군부의 지속적이고 심각한 종교자유 침해를 가장 강력한 표현으로 규탄한다"고 밝혔다. 카친미국침례교협회 회장 라셍 라비아(La Seng Labya) 목사는 미얀마 기독교인 보호를, 카친침례교회USA 총무 라캉 다우 카에(Lakang Dau Qae) 목사는 미얀마를 종교자유 특별우려국(CPC)으로 재지정할 것을 백악관에 요청했다.</p><p>미국 국제종교자유위원회(USCIRF)에 따르면 카친침례교총회(KBC) 전 총회장은 2019년 7월 백악관에서 트럼프 대통령을 만나 미얀마 기독교인 박해 문제를 논의했으며, 이후 체포돼 군사정권 법원에서 징역 6년을 선고받았다가 석방됐다. 미얀마는 1999년부터 2023년까지 CPC로 지정됐으나 이후로는 재지정되지 않았다. USCIRF는 2026년 연례보고서에서 국무부에 지정 복원을 권고했다.</p><p>ICC는 CPC 지정이 표적 제재와 원조 제한 등 미국의 추가 외교·경제 조치의 근거가 될 수 있다고 설명했다. 또 교회 점거가 오랜 분쟁 속에서 신앙생활을 지키려 애써 온 피란 카친 기독교 공동체에 또 하나의 타격이 되고 있다고 전했다. 한국 교회와 선교계도 카친 지역 교회의 상황에 지속적인 관심을 기울일 필요가 있다.</p>', '미얀마 카친주에서 군사정권과 연계된 민병대가 침례교회와 가톨릭교회 부지를 군사 목적으로 사용하고 있다고 국제기독연대(ICC)가 전했다. 미국 내 카친 교계 지도자들은 트럼프 행정부에 대응을 촉구했다.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Myitkyina%2C_Myanmar_%28Burma%29_-_panoramio_%281%29.jpg/1280px-Myitkyina%2C_Myanmar_%28Burma%29_-_panoramio_%281%29.jpg', '2026-10-14T08:30:00+09:00'::timestamptz, array['미얀마','카친','교회 점거','종교자유','동남아시아']::text[], 'wmt-src-02'),
  ('trends', '미얀마 기독교인들, 선교사 저드슨 생가 사들여 박물관으로', '<p>@@BYLINE@@&nbsp;미국에 사는 미얀마 디아스포라 기독교인들이 미얀마 교회가 ''영적 아버지''로 여기는 침례교 선교사 아도니람 저드슨(Adoniram Judson)의 생가를 사들여 기념 박물관으로 꾸몄다고 크리스채너티투데이(CT)가 12일(현지시간) 보도했다. 이 집은 매사추세츠주 몰든에 있는 18세기 식민지풍 주택으로, 저드슨이 태어나 네 살 반까지 살았던 곳이다.</p><img src="https://live.staticflickr.com/65535/51985016749_92e7d81cb9_b.jpg" alt="미국 매사추세츠주 세일럼 제일침례교회의 &#x27;선교사 창&#x27;. 1812년 미국의 첫 해외선교사들이 세일럼 항에서 떠난 일을 기린다 (사진=Salem State Archives and Special Collections, 플리커, CC BY 2.0)"><p><em>▲ 미국 매사추세츠주 세일럼 제일침례교회의 ''선교사 창''. 1812년 미국의 첫 해외선교사들이 세일럼 항에서 떠난 일을 기린다 (사진=Salem State Archives and Special Collections, 플리커, CC BY 2.0)</em></p><p>''올드 파스너지(Old Parsonage)''로 불리는 이 집은 1725년에 지어져 몰든에서 가장 오래된 건물로 꼽힌다. 몰든제일교회 목회자 사택으로 쓰이다가 1845년 노예제 폐지론자 조지 H. 윌슨에게 팔려 노예 탈출을 돕던 ''지하철도(Underground Railroad)''의 거점이 됐다. 이후 미국침례교해외선교회(American Baptist Foreign Mission Society)가 사들여 안식년 선교사 숙소로 썼지만, 1979년 무렵 개인 소유로 넘어가면서 일반인 방문이 막혔다.</p><p>2023년 이 지역에서 열린 미얀마 교회 집회에서 해외버마인기독교협회(Overseas Burmese Christian Fellowship)의 마웅 마웅 흐퉤(Maung Maung Htwe) 목사가 집을 사기 위한 헌금을 제안해 약 3천 달러가 모였다. 이듬해인 2024년 7월 양곤 출신 중국계 미얀마인 아서 저윈 첸(Arthur Zawwynn Chen) 목사가 집 앞을 지나다 매물 안내판을 발견했다. 이를 계기로 미국 각지의 미얀마 디아스포라 교회들이 뜻을 모아 아도니람저드슨유산재단(AJHF)을 꾸렸다.</p><p>교회들의 헌금과 개인 3명의 대출로 87만 5천 달러짜리 집의 계약금을 마련했고, 그해 9월 저드슨 출생 230여 년 만에 그의 사역 열매인 미얀마 기독교인들이 집의 주인이 됐다. 재단은 저드슨의 생일과 같은 날인 2025년 8월 9일 문을 열었다. 1층은 회의 공간과 미얀마 신학생 숙소로, 2층은 저드슨과 그의 아내들의 삶과 사역을 소개하는 전시실로 꾸몄다.</p><p>회중교회 목사의 아들로 1788년 8월 9일 태어난 저드슨은 1812년 아내 앤 등과 함께 인도 캘커타로 떠나며 공식 파송된 첫 미국인 선교사가 됐다. 항해 중 침례교 신학을 받아들여 자신을 파송한 회중교회 선교회에서 물러난 그는 1813년 버마에 도착했다. 첫 개종자에게 세례를 주기까지 6년이 걸렸고, 1824년 제1차 영국-버마 전쟁 때는 첩자로 의심받아 17개월간 투옥됐다. 그는 1834년 버마어 성경 전체 초역을 마쳤다.</p><p>CT에 따르면 그의 사역 열매는 오늘날 미얀마의 종교 지형에 남아 있다. 친족의 약 85%, 카친족의 약 90%가 기독교인이며, 침례교는 미얀마 최대 개신교 교단이다. 미얀마 교회는 저드슨이 양곤에 처음 도착한 7월 13일 무렵을 ''저드슨 주일''로 지키며 그의 선교 사역을 기념한다.</p><p>첸 목사는 저드슨에 대해 "그는 맡은 일을 끝까지 완수하고자 했고, 그 헌신이 그의 유산"이라고 말했다. 재단은 2021년 군사 쿠데타 이후 이어진 내전과 2025년 규모 7.7 지진으로 고통받는 미얀마 주민들을 돕는 모금도 벌였다. 마웅 목사는 전쟁이 길어지며 세상이 자신들을 잊었다고 낙심하는 이들에게 "하나님은 우리나라를 보고 계신다"고 말해 왔다고 전했다.</p><p>선교지에서 세워진 교회가 한 선교사의 생애를 기억하며 그의 생가를 되찾은 이야기는 선교의 열매가 세대를 넘어 이어진다는 점을 보여준다. 선교 역사를 기억하고 다음 세대에 전하는 일은 한국 선교계에도 울림을 준다.</p>', '미국 보스턴 일대의 미얀마 디아스포라 기독교인들이 침례교 선교사 아도니람 저드슨이 태어난 매사추세츠주 몰든의 집을 87만 5천 달러에 사들여 기념 박물관으로 꾸몄다고 크리스채너티투데이가 보도했다.', 'https://live.staticflickr.com/65535/51985016749_92e7d81cb9_b.jpg', '2026-10-13T07:30:00+09:00'::timestamptz, array['아도니람 저드슨','미얀마','선교 역사','디아스포라 교회']::text[], 'wmt-src-03'),
  ('asia-southeast', 'IMB 동남아 팀, 섬 주민에게 SNS 광고·영상으로 복음 전해', '<p>@@BYLINE@@&nbsp;IMB(미국 남침례교 국제선교이사회) 동남아시아 팀이 섬 지역 주민들에게 복음을 전하기 위해 소셜미디어를 활용한 디지털 사역에 힘을 쏟고 있다고 IMB가 5일(현지시간) 소개했다. 최근 이 팀이 한 젊은 여성에게 예수 이야기를 들어본 적이 있느냐고 묻자, 그는 온라인 영상을 통해 들었다고 답했다.</p><img src="https://live.staticflickr.com/7063/6972133929_94c584ef05_b.jpg" alt="인도네시아 술라웨시 토기안 제도 말렝에섬 앞바다에서 배를 모는 주민. 자료 사진 (사진=Arian Zwegers, 플리커, CC BY 2.0)"><p><em>▲ 인도네시아 술라웨시 토기안 제도 말렝에섬 앞바다에서 배를 모는 주민. 자료 사진 (사진=Arian Zwegers, 플리커, CC BY 2.0)</em></p><p>동남아시아에서 33년째 사역해 온 한 IMB 선교사는 처음 선교지에 왔을 때만 해도 마을 사람들을 한자리에 모아 영화 ''예수(JESUS)''를 함께 보는 방식이 일반적이었다고 회고했다. 그러나 지금은 섬 지역에서 그리스도에 대해 얼굴을 맞대고 대화하기가 더 어려워졌다고 IMB는 전했다.</p><p>IMB에 따르면 팀은 이 섬들을 자주 찾지만, 인구가 적고 애니미즘(정령숭배) 배경의 문화가 강한 곳에서 외국인이 머무르면 의심을 사기 쉬워 장기 사역이 쉽지 않다. 이 선교사는 요즘 젊은이들이 대면 대화보다 온라인 대화를 더 편하게 여기며, 섬 주민들도 마찬가지라고 설명했다. 현지인들에게 대면 영적 대화는 ''부담스러운 일''이 됐다는 것이다.</p><p>이에 따라 팀은 소셜미디어 플랫폼을 통한 디지털 사역을 현실적이고 효과적인 접촉 통로로 삼았다. 소셜미디어 마케팅 업체 위아소셜(We Are Social)에 따르면 동남아시아 인구의 82.4%가 인터넷을 사용한다. 이 선교사는 "아무리 외진 곳이라도 사람들은 휴대전화를 갖고 있다"며 주민들이 신호를 잡기 위해 높은 곳까지 올라가기도 한다고 전했다.</p><p>팀은 예수를 소개하는 광고와 영상 등 디지털 콘텐츠를 만들어 온라인에 올리고 있다. 광고를 누르면 기도해 주고 관계를 맺으며 영적 질문에 답해 줄 ''응답자''와 메시지를 주고받을 수 있는데, 응답자는 현지 신자나 선교사가 맡는다. 이 선교사는 "현지인들이 자기 휴대전화로 혼자 볼 때 더 마음을 여는 것 같다"고 말했다.</p><p>팀은 디지털 사역을 애니미즘 배경 주민들과의 첫 접촉에서 시작해 전도, 나아가 제자훈련으로 이어 가는 통로로 활용할 계획이다. 이 선교사는 스스로 연락해 오거나 대면으로는 복음에 반응하지 않았을 사람들에게도 문이 열릴 수 있다고 기대했다. IMB는 광고를 보고 응답자와 대화하는 주민들이 그로 인해 박해나 위해를 당할 수도 있다고 덧붙였다.</p><p>대면 접촉이 어려운 선교지에서 디지털 콘텐츠와 응답자 연결이 첫 만남의 통로가 될 수 있다는 점은 한국 선교계에도 참고가 된다. 동시에 온라인으로 복음에 반응한 이들의 안전을 지키는 일도 함께 고민해야 할 과제다.</p>', '대면 전도가 어려워진 동남아시아 섬 지역에서 IMB(미국 남침례교 국제선교이사회) 팀이 예수를 소개하는 온라인 광고와 영상을 만들어 현지인과 첫 접촉을 시도하고 있다. 광고를 누르면 응답자와 대화할 수 있다.', 'https://live.staticflickr.com/7063/6972133929_94c584ef05_b.jpg', '2026-10-06T08:00:00+09:00'::timestamptz, array['동남아시아','디지털 선교','IMB','애니미즘','전도']::text[], 'wmt-src-04'),
  ('asia-northeast', 'IMB 서울 선교사 부부 "화려한 한국 뒤 청년들의 아픔 본다"', '<p>@@BYLINE@@&nbsp;서울에서 10년 넘게 사역해 온 IMB(미국 남침례교 국제선교이사회) 선교사 부부와 미국 교회 자원봉사자들이 현지 교회와 함께한 ''서브 투어 서울(Serve Tour Seoul)'' 이야기를 IMB가 1일(현지시간) 소개했다. 이 글은 IMB와 북미선교이사회(NAMB)가 함께 운영하는 긍휼 사역 기관 센드릴리프(Send Relief)가 처음 게재했다.</p><img src="https://live.staticflickr.com/5214/5464351080_f701992af3_b.jpg" alt="남산 N서울타워에서 내려다본 서울 도심. 자료 사진 (사진=InSapphoWeTrust, 플리커, CC BY-SA 2.0)"><p><em>▲ 남산 N서울타워에서 내려다본 서울 도심. 자료 사진 (사진=InSapphoWeTrust, 플리커, CC BY-SA 2.0)</em></p><p>훈(Hun)·은주(Eunjoo) 선교사 부부는 2025년 남침례교 ''국제선교 기도주간''에 소개된 인물들이다. 훈 선교사는 많은 사람이 K팝과 K컬처, 첨단 기술, 화장품을 떠올리며 한국을 흥미롭고 성공한 나라로 여기지만 "지금 많은 한국 사람들이 힘들어하고 있다"고 말했다.</p><p>훈 선교사는 이 숨겨진 아픔을 ''한(恨)''이라는 말로 설명하곤 한다. IMB는 한을 전쟁과 분단, 상실의 세월 속에 형성된 깊은 슬픔이자 견뎌 내려는 조용한 의지로 소개했다. 부부는 매주 만나는 청년들에게서 외로움과 끝없는 기대 속에 성공의 겉모습 아래 삶의 의미를 묻는 모습을 본다고 했다. IMB는 자살이 한국 10대와 청년층의 주요 사망 원인 가운데 하나라고 전했다.</p><p>서브 투어는 건축이나 보수 같은 노동 봉사가 아니라 현지 교회가 이미 해 오던 사역에 함께하는 방식으로 진행됐다. 지난 5월 미국 7개 교회에서 온 자원봉사자 27명은 10일 동안 서울과 파주, 광주의 현지 교회와 함께 영어 교실과 어린이 캠프를 열고, 동네를 돌며 기도하고, 음식을 나누고, 대학생들과 대화했다. 캘리포니아주 리버사이드 샌들스교회의 닉 홀스트는 "우리는 사람들을 만나러 왔다"고 말했다.</p><p>캘리포니아주 베이커즈필드 밸리침례교회의 제러미 도일 선교목사는 첫날 학생 2명으로 시작한 영어 회화 모임이 둘째 날 8명으로 늘었다고 전했다. 자원봉사자들은 인근 기독교 학교에서 영어 캠프를 열어 단어와 성경 이야기를 함께 가르쳤고, 복음을 간단히 설명하는 ''3서클(3 Circles)'' 전도법도 소개했다. 일정이 끝날 무렵에는 영어를 연습하러 왔던 일부 한국 학생들이 직접 다른 이들에게 신앙을 전했다.</p><p>시카고 업타운침례교회의 닉 김 목사 팀은 토브교회(TOV Church)와 함께 이 교회의 첫 성경학교(VBS)를 열고 연세대학교를 위해 기도했다. 이후 비무장지대(DMZ)를 찾아 준 유(Jun Yu) 목사와 함께 남북한을 위해 기도했다. 아버지가 북한에서, 자신은 남한에서 태어난 김 목사는 그 기도가 "추상적인 요청이라기보다 우리 가족의 이야기처럼 느껴졌다"고 말했다.</p><p>훈·은주 선교사 부부는 서울의 48개 대학에서 현지 교회들이 대학생에게 다가가도록 교회 개척과 영어 회화 모임, 트라우마 치유 훈련, 성경 기반 사역을 돕고 있다. 부부는 2028년 말까지 서울의 48개 대학 캠퍼스마다 교회가 개척되기를 기도하고 있다.</p><p>외국 선교사의 눈에 비친 한국 청년들의 아픔은 한국 교회가 가장 가까운 선교지인 다음 세대를 어떻게 품을지 돌아보게 한다. 한국 교회가 받는 자리에서 다시 선교의 현장이 되고 있다는 점도 눈여겨볼 대목이다.</p>', '서울에서 10년 넘게 사역한 IMB 선교사 부부와 미국 7개 교회 자원봉사자 27명이 지난 5월 서울·파주·광주의 현지 교회와 함께 대학생·청소년 사역을 펼쳤다. 부부는 2028년까지 서울 48개 대학마다 교회가 세워지길 기도하고 있다.', 'https://live.staticflickr.com/5214/5464351080_f701992af3_b.jpg', '2026-10-02T08:00:00+09:00'::timestamptz, array['한국','서울','대학생 선교','단기선교','IMB']::text[], 'wmt-src-05'),
  ('world-americas', '美 난민 상한 1만7500명…박해받는 종교 소수자엔 ''닫힌 문''', '<p>@@BYLINE@@&nbsp;미국 정부가 2027 회계연도 난민 수용 상한을 1만 7,500명으로 정하고 이를 주로 백인 남아프리카공화국인, 이른바 아프리카너에게 배정했다고 크리스채너티투데이(CT)가 9일(현지시간) 보도했다. 정부는 약 2주 전 공개한 ''2027 회계연도 난민 수용에 관한 대통령 결정''에서 미국 난민수용프로그램(USRAP)은 국가 이익에 해당하는 경우를 제외하고 계속 중단된다고 명시했다.</p><img src="https://live.staticflickr.com/3693/9638143042_28d85aa871_b.jpg" alt="요르단 자타리 난민촌의 큰길. 자료 사진 (사진=영국 국제개발부(DFID), 플리커, CC BY 2.0)"><p><em>▲ 요르단 자타리 난민촌의 큰길. 자료 사진 (사진=영국 국제개발부(DFID), 플리커, CC BY 2.0)</em></p><p>월드릴리프(World Relief)의 해나 대니얼 정부관계 국장은 CT에 "난민 수를 제한할 뿐 아니라 프로그램 접근 대상을 단 하나의 국적으로 제한하는 현 정책이 이어져 매우 실망스럽다"고 말했다. CT는 특정 국적에 수용 인원을 주로 배정하는 결정이 박해받는 종교 소수자뿐 아니라, 수십 년째 재정착을 기다려 온 이들을 포함해 무력 분쟁과 전쟁, 폭력을 피해 온 수많은 사람을 배제한다고 지적했다.</p><p>월드릴리프와 오픈도어 미국 지부(Open Doors US)의 공동 보고서에 따르면 2026 회계연도에 미국에 입국한 박해받는 기독교인이나 다른 종교 소수자 난민은 한 명도 없었다. CT는 상황이 바뀌지 않으면 2027 회계연도에도 같은 결과가 나올 것으로 내다봤다. 박해받는 종교 소수자의 재정착을 돕기 위해 1990년 만들어진 로텐버그 수정안(Lautenberg Amendment) 프로그램도 난민 프로그램 중단으로 트럼프 행정부에서 처음으로 작동을 멈췄다.</p><p>1980년 제정된 난민법은 대통령이 의회와 함께 매년 난민 수용 상한을 정하도록 했다. 법 제정 당시 상한은 23만 1,700명이었고, 오바마 행정부 시기에는 평균 7만 3천 명, 바이든 행정부 시기에는 연 12만 5천 명이었다. 트럼프 대통령은 지난해 상한을 프로그램 도입 이후 최저인 7,500명으로 정했다가, 아프리카너들이 ''인종적 동기의 폭력''으로 ''예기치 못한 긴급 난민 상황''에 처했다고 주장하며 1만 7,500명으로 늘렸다.</p><p>2025년 1월 난민 프로그램이 중단되면서 트럼프 행정부는 수년간의 심사와 승인 절차를 마친 난민들의 항공편 1만 건 이상을 취소했다. 미네소타주 난민 재정착 기관 어라이브 미니스트리즈(Arrive Ministries)의 루스 르페이지 난민서비스 국장은 미네소타에 가족이 있는 16명의 입국 일정이 취소됐고, 가족들이 지금도 언제 재회할 수 있느냐고 묻는다고 전했다. 국제구조위원회(IRC)는 캘리포니아에 사는 약혼녀·어머니와 떨어져 있는 이란의 아르메니아계 기독교인 등 입국을 기다리는 난민 사례를 소개했다.</p><p>대니얼 국장은 몇 달 전 부룬디의 한 난민캠프를 방문했을 때 콩고민주공화국의 폭력을 피해 온 장애가 있는 한 남성이 흐느끼며 왜 더는 받아 주지 않느냐고 물었다고 전했다. 미국에서 치료를 받을 예정이던 그는 지금 캠프에 발이 묶여 있다. 대니얼 국장은 "전 세계 수많은 난민이 비슷한 상황에 갇혀 있다"고 말했다.</p><p>IRC의 켄지 기즈카 정책국장은 대통령 결정문이 수용 인원을 ''주로'' 아프리카너에게 배정한다고 표현한 점에 주목했다. 그는 시민들이 지역구 의원을 통해 다른 국적 난민도 포함해 달라고 대통령에게 요청할 수 있으며, 해외에 발이 묶인 난민을 기다리는 이들의 목소리를 전하는 데 신앙 공동체가 역할을 할 수 있다고 말했다.</p><p>난민 문제는 국내 이주민 선교에 관심을 기울여 온 한국 교회와도 맞닿아 있다. 박해받는 신자들이 피난처를 찾지 못하는 현실은 세계 교회가 함께 기도하고 고민해야 할 과제로 남아 있다.</p>', '미국 정부가 2027 회계연도 난민 수용 상한을 1만 7,500명으로 정하고 대부분을 백인 남아공인(아프리카너)에게 배정했다. 2026 회계연도에는 박해받는 기독교인 등 종교 소수자 난민이 한 명도 입국하지 못했다.', 'https://live.staticflickr.com/3693/9638143042_28d85aa871_b.jpg', '2026-10-10T08:00:00+09:00'::timestamptz, array['미국','난민','종교 소수자','박해','트럼프 행정부']::text[], 'wmt-src-06'),
  ('ch-mobilization', 'IMB, 신임 선교사 46명 파송…일부는 보안 위해 얼굴 가려', '<p>@@BYLINE@@&nbsp;IMB(미국 남침례교 국제선교이사회)가 9월 16일(현지시간) 버지니아주 사우스체스터필드의 하이츠침례교회에서 올해 세 번째 ''파송 축하 예배(Sending Celebration)''를 열고 선교사 46명을 파송했다고 밝혔다. IMB 이사회는 이들과 함께, 이날 참석하지 않은 캐나다 선교사 3명의 임명도 승인했다.</p><img src="https://live.staticflickr.com/2358/2190339380_0304c7b468_b.jpg" alt="공항 출국 안내판. 자료 사진 (사진=Snipergirl, 플리커, CC BY 2.0)"><p><em>▲ 공항 출국 안내판. 자료 사진 (사진=Snipergirl, 플리커, CC BY 2.0)</em></p><p>일부 선교사는 화면 뒤에 실루엣으로만 모습을 드러냈고, 일부는 다른 사람의 목소리로 간증을 전했다. 토드 래퍼티 IMB 수석부총재는 "이 형제자매들은 어렵고 접근하기 힘든 곳으로 간다"고 말했다. IMB는 이들이 복음 전파가 불법이거나 위험한 지역으로 향하기 때문에 얼굴을 공개할 수 없었다고 설명했다.</p><p>브라질의 5대째 목회자 가정에서 자란 다닐로 안투네스 선교사는 쿠바 선교 여행을 계기로 사역에 뛰어들었다. 미국에서 신학교에 다니며 스페인어권 교회를 목회하고 텍사스 남부에서 영어권 교회 개척을 도운 그는 아내 해나 선교사와 함께 스페인에서 복음이 가장 덜 전해진 지역으로 간다. 텍사스 브라운스빌제일침례교회가 파송한 부부는 이 지역의 첫 IMB 선교사가 된다. 다닐로 선교사는 "선교지에 가는 것만이 아니라 선교지에 머물기를 원한다"고 말했다.</p><p>음악 교사인 더스티·애슐리 잭슨 선교사 부부는 필리핀의 선교사 자녀 학교로 간다. 부부는 앞서 한국의 한 기독교 국제학교에서 가르치며 학생들의 학업과 신앙을 함께 돌보는 일의 중요성을 깨달았다. 뉴멕시코주 파밍턴의 그레이스힐교회가 후원하는 부부는 네 자녀와 함께 필리핀으로 이주해, 더스티는 오케스트라를, 애슐리는 중고등부 합창을 맡는다.</p><p>1980년대 미국으로 이주해 한인 교회에 다니던 존·해나 김 선교사 부부는 잠비아로 돌아간다. 둘 다 기독교 가정에서 자라지 않았지만 이민 후 각자 그리스도를 영접했다. 30년 넘게 한인 사역을 해 온 부부는 2022년 IMB에 합류해 잠비아에서 목회자와 성경학교 학생들을 가르쳐 왔다.</p><p>조지아주 페이엣빌제일침례교회가 파송한 김 선교사 부부는 잠비아에서 신학교 다섯 곳의 책임자로 신학교육과 제자훈련을 이끌 예정이다. 존 선교사는 "사역은 프로그램만이 아니라 사람에게 투자하고 그들과 함께 걷는 것"이라고 말했다.</p><p>플로리다주 펜서콜라 올리브침례교회의 테드 트레일러 담임목사는 이사야 41장 10~14절을 본문으로 의심과 두려움에 맞서라고 권면하며, 남침례교인들이 헌금과 기도로 선교사들과 함께하겠다고 다짐했다. 캐럴 파이퍼 IMB 이사회 의장은 가족과 친구들이 선교사들을 둘러싸고 기도하도록 이끌었다. 다음 파송 축하 예배는 11월 9일 오하이오주 케터링제일침례교회에서 열린다.</p><p>보안이 필요한 지역으로 가는 선교사의 얼굴과 목소리를 가린 채 파송하는 방식은 한국 교회의 파송 예배에도 참고가 된다. 이민자로 미국에 건너가 오랫동안 한인 사역을 해 온 부부가 아프리카 신학교육에 헌신하는 모습도 눈길을 끈다.</p>', 'IMB(미국 남침례교 국제선교이사회)가 9월 16일 버지니아주에서 파송 축하 예배를 열고 선교사 46명을 파송했다. 복음 전파가 불법이거나 위험한 지역으로 가는 일부 선교사는 보안을 위해 얼굴과 목소리를 가렸다.', 'https://live.staticflickr.com/2358/2190339380_0304c7b468_b.jpg', '2026-09-18T08:00:00+09:00'::timestamptz, array['IMB','선교사 파송','파송 예배','선교 동원','선교지 보안']::text[], 'wmt-src-07'),
  ('cm-field', '[창간 기획] 왜 치앙마이에서 시작하는가', '<p>@@BYLINE@@&nbsp;월드미션타임즈가 태국 북부 치앙마이에서 첫발을 내디딘다. 치앙마이는 태국 북부 최대 도시이자 옛 란나 왕국의 중심지로, 오랫동안 북부 태국 선교의 거점 역할을 해 왔다. 한국어로 세계선교 소식을 전하는 매체가 왜 이 도시에서 시작하는지, 그 배경을 짚어본다.</p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Tha_Phae_Gate%2C_Chiang_Mai_%2848108299477%29.jpg/1280px-Tha_Phae_Gate%2C_Chiang_Mai_%2848108299477%29.jpg" alt="태국 치앙마이 옛 성곽의 동문인 타패 문. 자료 사진 (사진=Fabio Achilli, 위키미디어 공용, CC BY 2.0)"><p><em>▲ 태국 치앙마이 옛 성곽의 동문인 타패 문. 자료 사진 (사진=Fabio Achilli, 위키미디어 공용, CC BY 2.0)</em></p><p>북부 태국 개신교 선교의 역사는 1867년으로 거슬러 올라간다. 미국 장로교 선교사 대니얼 맥길버리(Daniel McGilvary)가 이해 치앙마이에 들어와 사역을 시작했고, 이것이 북부 태국 개신교 선교의 출발점이 됐다. 선교사들은 복음 전도와 함께 교육과 의료 사역을 펼쳤다.</p><p>선교의 역사는 지역 사회에 기관으로도 남았다. 치앙마이의 맥코믹 병원과 파얍대학교는 이 선교 역사 속에서 세워진 기독교 기관으로, 지금도 운영되고 있다.</p><p>치앙마이를 중심으로 한 북부 산간 지역에는 여러 산지 종족(고산족)이 살고 있다. 이들을 대상으로 한 복음 전도와 교회 개척, 교육 사역은 오랫동안 북부 태국 선교의 중요한 축이 돼 왔다. 북부 태국이 미얀마, 라오스와 국경을 맞대고 있다는 점도 이 지역을 주변 나라와 이어지는 선교 현장으로 만든다.</p><p>그러나 태국 전체로 보면 복음화의 과제는 여전히 크다. 조슈아 프로젝트에 따르면 태국 인구 가운데 기독교인은 1.8%, 복음주의 기독교인은 0.7%에 그친다. 태국에 사는 110개 종족 가운데 73개는 미전도 종족으로 분류된다.</p><p>오늘날 치앙마이에는 여러 나라에서 온 선교단체와 선교사들이 모여 있다. 선교사 자녀를 위한 학교도 자리하고 있어, 이 도시는 동남아 각지에서 사역하는 선교사들이 교육과 훈련, 교제를 위해 찾는 곳이기도 하다. 한국 선교사들도 이곳을 거점으로 태국과 주변 지역에서 사역하고 있다.</p><p>월드미션타임즈는 이 도시에서 선교 현장의 소식을 가까이에서 듣고 전하는 일부터 시작한다. 치앙마이와 태국, 동남아시아의 선교 현장을 시작으로 세계선교 동향과 미전도 종족, 선교사들의 이야기로 보도 범위를 넓혀 갈 계획이다. 선교지 보안을 최우선으로 삼아 현지 신자와 선교사를 보호하는 원칙도 지켜 나간다.</p><p>150여 년 전 한 선교사가 들어선 도시에서 한국 교회와 세계 선교 현장을 잇는 새로운 소식의 통로가 열린다. 월드미션타임즈는 한국 교회의 선교사와 후원자, 선교단체가 선교 현장을 더 깊이 이해하도록 돕는 매체가 되고자 한다.</p>', '월드미션타임즈가 첫 거점으로 태국 북부 치앙마이를 택했다. 150여 년 전 미국 장로교 선교사의 발걸음에서 시작된 북부 태국 선교의 역사와 산지 종족 사역, 여러 나라 선교 공동체가 모인 이 도시의 의미를 짚어본다.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Tha_Phae_Gate%2C_Chiang_Mai_%2848108299477%29.jpg/1280px-Tha_Phae_Gate%2C_Chiang_Mai_%2848108299477%29.jpg', '2026-10-14T06:00:00+09:00'::timestamptz, array['치앙마이','태국 선교','창간 기획','대니얼 맥길버리','미전도 종족']::text[], 'wmt-explainer-1'),
  ('trends-data', '숫자로 본 한국선교 2024…장기 선교사 2만1621명, 감소·고령화', '<p>@@BYLINE@@&nbsp;한국 국적 장기 선교사 수가 줄고 있다. 국내 기독교 언론 보도에 따르면 한국세계선교협의회(KWMA)와 한국선교연구원(KRIM)이 2025년 3월 발표한 「2024 한국선교 현황 통계조사」에서 2024년 말 기준 한국 국적 장기 선교사는 171개국에서 사역하는 2만 1,621명으로 집계됐다. 이는 전년(2만 1,917명)보다 296명 줄어든 수치로, 선교사 수는 2020년부터 감소 추세를 이어 가고 있다.</p><img src="https://live.staticflickr.com/803/39227752970_4ae9d65eaf_b.jpg" alt="서울 도심 풍경. 자료 사진 (사진=arnaudmatar, 플리커, CC0)"><p><em>▲ 서울 도심 풍경. 자료 사진 (사진=arnaudmatar, 플리커, CC0)</em></p><p>이번 조사는 228개 교단과 선교단체를 대상으로 했다. 2024년 새로 파송된 선교사는 634명이었고, 파송 대륙별로는 아시아가 65.2%를 차지했다.</p><p>고령화도 뚜렷하다. 선교사 평균 연령은 2020년 52.1세에서 2022년 53.1세로 높아졌다. 은퇴 선교사는 443명으로 전년 274명보다 크게 늘었다.</p><p>한국 선교단체가 파송한 타국적 선교사는 76개국 출신 986명으로 집계됐다. 한국 선교가 한국인만의 사역을 넘어 여러 나라 출신 동역자와 함께하는 방향으로 넓어지고 있음을 보여주는 대목이다.</p><p>국내로 들어온 이주민을 대상으로 사역하는 선교사는 전체의 4.2%였다. 이 가운데 80.9%는 파송단체가 없는 것으로 나타나, 국내 이주민 사역자를 위한 행정 지원과 멤버케어 체계가 과제로 떠올랐다.</p><p>통계에는 한계도 있다. 교단이나 선교단체를 거치지 않고 교회가 직접 파송한 선교사는 집계에서 빠질 수 있어, 실제 한국 선교사 규모는 통계와 차이가 날 수 있다.</p><p>세계로 눈을 돌리면, 미국 고든콘웰신학교 세계기독교연구센터는 2026년 세계 타문화 선교사를 약 45만 5천 명으로 추정한다. 조슈아 프로젝트에 따르면 전 세계 1만 6,419개 종족 가운데 7,163개(43.6%)가 여전히 미전도 종족으로 분류된다.</p><p>선교사 수의 감소와 고령화는 한국 교회에 은퇴 선교사 돌봄과 다음 세대 선교 동원이라는 과제를 함께 던지고 있다. 월드미션타임즈는 한국 선교의 흐름을 숫자와 현장 이야기로 계속 짚어 갈 예정이다.</p>', 'KWMA·KRIM의 「2024 한국선교 현황 통계조사」에 따르면 2024년 말 한국 국적 장기 선교사는 171개국 2만 1,621명으로 전년보다 296명 줄었다. 은퇴 선교사는 443명으로 늘었고 평균 연령도 높아지고 있다.', 'https://live.staticflickr.com/803/39227752970_4ae9d65eaf_b.jpg', '2026-10-14T06:30:00+09:00'::timestamptz, array['한국선교 통계','KWMA','선교사 고령화','미전도 종족','선교 동향']::text[], 'wmt-explainer-2')
) as v(slug, title, body, excerpt, thumb, published_at, tags, guid)
join categories c on c.outlet_id = ctx.outlet_id and c.slug = v.slug
where not exists (select 1 from articles a where a.outlet_id = ctx.outlet_id and a.title = v.title);

-- 기자명 '관리자', 기자 이메일 비우기, AI 메모(확인할 점·원문 주소)
--   (기자 이메일은 DB 규칙이 대표 이메일로 채우므로, 잠깐 그 규칙을 끄고 비운 뒤 다시 켠다)
do $fix$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'articles' and column_name = 'byline') then
    update articles a set byline = '관리자'
    from outlets o where a.outlet_id = o.id and o.name = '월드미션타임즈' and a.body like '<p>[%=관리자 기자]%' and a.byline is distinct from '관리자';
  end if;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'articles' and column_name = 'byline_email') then
    if exists (select 1 from pg_trigger where tgname = 'articles_byline_email') then
      alter table articles disable trigger articles_byline_email;
    end if;
    update articles a set byline_email = null
    from outlets o where a.outlet_id = o.id and o.name = '월드미션타임즈' and a.body like '<p>[%=관리자 기자]%';
    if exists (select 1 from pg_trigger where tgname = 'articles_byline_email') then
      alter table articles enable trigger articles_byline_email;
    end if;
  end if;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'articles' and column_name = 'ai_notes') then
    update articles a set ai_notes = v.notes
    from outlets o, (values
      ('네팔 경찰, 신학교 모임 참석한 한국인 기독교인 24명 체포', '• 확인할 점: 체포된 한국인의 신원·소속·현 상태는 원문에 없음. 외교부·주네팔 대사관 등 공식 발표 확인 전에는 추가 내용을 쓰지 않음.
